import{_ as e,o as d,c as a,a3 as r}from"./chunks/framework.BLaSdaBb.js";const u=JSON.parse('{"title":"NACP 内部记录表","description":"","frontmatter":{},"headers":[],"relativePath":"transport/nacp/tables.md","filePath":"transport/nacp/tables.md","lastUpdated":1788343005000}'),o={name:"transport/nacp/tables.md"};function s(c,t,n,p,b,i){return d(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="nacp-内部记录表" tabindex="-1">NACP 内部记录表 <a class="header-anchor" href="#nacp-内部记录表" aria-label="Permalink to &quot;NACP 内部记录表&quot;">​</a></h1><p>NACP 内部使用七张表记录连接、等待中的回包、订阅和可靠传输状态。</p><table tabindex="0"><thead><tr><th>表</th><th>内容</th><th>写入时机</th><th>清理时机</th></tr></thead><tbody><tr><td><code>peerAppTable</code></td><td>appId 与 peerId 的链路状态，以及 Gateway 槽位</td><td>Register 握手与绑定时</td><td>Unregister / 宽限超时</td></tr><tr><td><code>pendingTable</code></td><td>等待 Response 的调用</td><td>发出需要 Response 的消息时</td><td>收到 Response，或超时、遗忘时批量失败</td></tr><tr><td><code>subscribeTable</code></td><td>为对端在本 App EventBus 上建立的 Listener</td><td>onSubscribe，包含 AutoSubscribe</td><td>onUnsubscribe / 遗忘</td></tr><tr><td><code>listenTable</code></td><td>本 App 等待对端 Notify 的 Listener</td><td>subscribe 出站前，包含 AutoSubscribe</td><td>unsubscribe / 遗忘</td></tr><tr><td><code>backlogTable</code></td><td>尚未出线或等待重发的消息</td><td>普通消息进入出站流程时</td><td>成功出线 / 溢出 / 遗忘</td></tr><tr><td><code>ackPendingTable</code></td><td>已出站、正在等待 ACK 的消息</td><td>可靠消息出站后</td><td>收到 ACK / 离线时移回 backlog</td></tr><tr><td><code>inboundReceivedTable</code></td><td>已处理的可靠入站消息 ID</td><td>入站处理前</td><td>遗忘 / 超容量时逐出最早记录</td></tr></tbody></table><p>表的生命周期与断线清理见<a href="/transport/nacp/lifecycle">生命周期</a>，AutoSubscribe 如何同时使用两张订阅表见 <a href="/transport/nacp/auto-subscribe">AutoSubscribe</a>。</p>',4)])])}const _=e(o,[["render",s]]);export{u as __pageData,_ as default};
